class TransferError(Exception):
    pass

class InsufficientFunds(TransferError):
    pass

class UnknownAccount(TransferError):
    pass

def transfer(accounts, source, target, amount):
    try:
        source_balance = accounts[source]
        accounts[target]
    except KeyError as error:
        raise UnknownAccount(f"bilinmeyen hesap: {error.args[0]}") from error
    if amount > source_balance:
        raise InsufficientFunds(f"yetersiz bakiye: {source}")
    accounts[source] -= amount
    accounts[target] += amount

