class Player:
    def __init__(self, name):
        self.name = name
        self.scores = []

    def add(self, points):
        self.scores.append(points)

    def total(self):
        return sum(self.scores)

    def best(self):
        return max(self.scores, default=0)

    def label(self):
        return self.name

class Captain(Player):
